<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import{tick}from'svelte';
 import type{DesignSnapshot,DesignElement,DesignOperation}from'@schubert/contracts';
 import ReferencePicker from'../ReferencePicker.svelte';
 import MeasurementField from'./MeasurementField.svelte';
 import{applyOperations,parseMillimetres}from'@schubert/geometry';
 import{describeStudioIssue}from'./issues.ts';
 let{snapshot,element,documents=[],materials=[],finishes=[],rules=[],actorId='',canConfirm=false,onchange}:{snapshot:DesignSnapshot;element:DesignElement;documents?:any[];materials?:any[];finishes?:any[];rules?:any[];actorId?:string;canConfirm?:boolean;onchange:(ops:DesignOperation[])=>void}=$props();
 let sourceId=$state('');
 let slopeKey=$state(''),slopeError=$state(''),slopeDraft=$state({sx:'0',sy:'0',sz:'0',ex:'0',ey:'0',ez:'0'});
 function resetSlope(){if(element.kind!=='slope')return;slopeDraft={sx:element.start.xMm,sy:element.start.yMm,sz:element.start.zMm,ex:element.end.xMm,ey:element.end.yMm,ez:element.end.zMm};slopeError='';}
 $effect(()=>{if(element.kind==='slope'){const key=element.id+JSON.stringify([element.start,element.end]);if(slopeKey!==key){slopeKey=key;resetSlope();}}});
 function applySlopePoints(event:SubmitEvent){event.preventDefault();slopeError='';if(element.kind!=='slope')return;try{const values=Object.fromEntries(Object.entries(slopeDraft).map(([key,value])=>[key,parseMillimetres(value)]));if(Object.values(values).some(value=>value===null))throw Error('Alle sechs Punktkoordinaten eindeutig in mm angeben.');const operation:DesignOperation={type:'set_slope_spec',elementId:element.id,start:{xMm:values.sx!,yMm:values.sy!,zMm:values.sz!},end:{xMm:values.ex!,yMm:values.ey!,zMm:values.ez!}};applyOperations(snapshot,[operation]);onchange([operation]);}catch(problem){slopeError=describeStudioIssue(snapshot,(problem as Error).message).message;}}
 const hosts=$derived(snapshot.elements.filter(e=>e.id!==element.id&&['stone_piece','surface',...(element.kind==='slope'?[]:['catalog_object','wall'])].includes(e.kind)));
 const joints=$derived(snapshot.elements.filter(e=>e.kind==='connection'&&e.connectionType==='joint'));
 const choices=(rows:any[])=>rows.map(r=>({id:r.version_id??r.id,name:r.name??r.title??'Gespeicherte Fassung'}));
 function host(value:string){if(element.kind==='connection')onchange([{type:'set_connection_spec',elementId:element.id,connectionType:element.connectionType,specificationVersionId:element.specificationVersionId,hostElementId:value||null}]);else if(element.kind==='clearance')onchange([{type:'set_clearance_spec',elementId:element.id,ruleVersionId:element.ruleVersionId,hostElementId:value||null}]);else if(element.kind==='slope'&&value)onchange([{type:'set_slope_spec',elementId:element.id,hostElementId:value}]);}
 function rule(value:string){if(element.kind==='connection')onchange([{type:'set_connection_spec',elementId:element.id,connectionType:element.connectionType,specificationVersionId:value||null,hostElementId:element.hostElementId}]);else if(element.kind==='clearance')onchange([{type:'set_clearance_spec',elementId:element.id,ruleVersionId:value||null,hostElementId:element.hostElementId}]);else if(element.kind==='slope')onchange([{type:'set_slope_spec',elementId:element.id,ruleVersionId:value||null}]);else if(element.kind==='surface')onchange([{type:'set_surface_spec',elementId:element.id,ruleVersionId:value||null}]);else if(element.kind==='technical_note')onchange([{type:'set_technical_note',elementId:element.id,text:element.text,category:element.category,ruleVersionId:value||null}]);}
 async function addSource(){if(!sourceId||element.sourceEvidenceVersionIds.includes(sourceId))return;onchange([{type:'set_element_sources',elementId:element.id,sourceEvidenceVersionIds:[...element.sourceEvidenceVersionIds,sourceId]}]);await tick();sourceId='';}
 function sourceName(id:string){return documents.find(d=>(d.version_id??d.document_version_id??d.id)===id)?.name??'Gespeicherte Quellenversion';}
</script>
<section class="technical-references"><h3>Technische Bezüge & Quellen</h3>
{#if element.kind==='stone_piece'}
 <label>Bauteilart<select use:searchableSelect={element.purpose} value={element.purpose} onchange={event=>onchange([{type:'set_stone_spec',elementId:element.id,purpose:event.currentTarget.value as any}])}><option value="memorial">Grabmal / Stele</option><option value="countertop">Waschtisch- / Arbeitsplatte</option><option value="floor">Bodenplatte</option><option value="wall">Wandplatte</option><option value="sill">Fensterbank</option><option value="step">Stufe / Podest</option><option value="other">Anderes Bauteil</option></select></label>
 <label for={'stone-finish-'+element.id}>Zusätzlich bestätigter Oberflächenstand</label><ReferencePicker id={'stone-finish-'+element.id} reference="planning-finishes" initial={choices(finishes)} value={element.finishSpecVersionId??''} onchange={value=>onchange([{type:'set_stone_spec',elementId:element.id,finishSpecVersionId:value||null}])}/>
 <details class="technical-details"><summary>Rohmaße für die Fertigung</summary><p>Ausdrückliche Rohlingmaße im lokalen Bauteilbezug. Sie verändern die Fertigkontur nicht. Aderung, Bearbeitungszugaben, Sägefuge und Zuschnitt bleiben eigene fachliche Entscheidungen.</p>
 {#each [['roughWidthMeasureId','Rohmaß X'],['roughHeightMeasureId','Rohmaß Y'],['roughThicknessMeasureId','Rohstärke']] as [field,label]}<MeasurementField {snapshot} measureId={(element as any)[field]??null} {label} elementId={element.id} {field} {actorId} {canConfirm} evidence={documents} onchange={onchange}/>{/each}
</details>{/if}
{#if element.kind==='surface'}<label>Flächenart<select use:searchableSelect={element.surfaceType} value={element.surfaceType} onchange={event=>onchange([{type:'set_surface_spec',elementId:element.id,surfaceType:event.currentTarget.value as any}])}><option value="floor">Boden</option><option value="wall">Wand</option><option value="ceiling">Decke</option><option value="shower">Dusche</option><option value="inscription">Beschriftungsfläche</option></select></label><label for={'substrate-'+element.id}>Bestätigter Untergrundmaterialstand</label><ReferencePicker id={'substrate-'+element.id} reference="material-versions" initial={choices(materials)} value={element.substrateVersionId??''} onchange={value=>onchange([{type:'set_surface_spec',elementId:element.id,substrateVersionId:value||null}])}/>
 <h4>Bewegungs- und Anschlussfugen</h4><p>Ordnen Sie konkrete Fugenpunkte und die zugehörigen Fachunterlagen zu. Aus einer Markierung wird keine ungeprüfte Fugenbreite oder pauschale Abzugsregel abgeleitet.</p>{#each joints as joint}<label class="check"><input type="checkbox" checked={element.movementJointElementIds.includes(joint.id)} onchange={event=>{if(element.kind==='surface')onchange([{type:'set_surface_spec',elementId:element.id,movementJointElementIds:event.currentTarget.checked?[...element.movementJointElementIds,joint.id]:element.movementJointElementIds.filter(id=>id!==joint.id)}]);}}/>{joint.label}</label>{:else}<p>Eine Fuge zuerst mit dem Werkzeug „Anschluss“ anlegen und als „Fuge / Anschluss“ kennzeichnen.</p>{/each}
{/if}
{#if element.kind==='connection'||element.kind==='clearance'||element.kind==='slope'}<label>Fachlicher Bezug<select use:searchableSelect={element.hostElementId??''} value={element.hostElementId??''} onchange={event=>host(event.currentTarget.value)}><option value="" disabled={element.kind==='slope'}>{element.kind==='slope'?'Bezugsfläche auswählen':'Eigenständiger Bezug'}</option>{#each hosts as candidate}<option value={candidate.id}>{candidate.label}</option>{/each}</select></label><p>Der fachliche Bezug und das Koordinatensystem sind getrennt. Die lokale Lage bearbeiten Sie über die Positionsfelder beziehungsweise die Gefällewerte.</p>{/if}
{#if element.kind==='slope'}<form class="slope-points" onsubmit={applySlopePoints}><h4>Gefällepunkte im Bauteilbezug</h4><p>Beide Punkte liegen im lokalen Bezug der gewählten Fläche. Daraus folgen Richtung, horizontale Lauflänge und Höhenunterschied. Vorhandene bestätigte Aufmaße werden dabei nicht durch Wunschmaße ersetzt.</p><div class="point-fields">{#each [['sx','Anfang X'],['sy','Anfang Y'],['sz','Anfang Z'],['ex','Ende X'],['ey','Ende Y'],['ez','Ende Z']] as [field,label]}<label>{label} (mm)<input inputmode="decimal" value={slopeDraft[field as keyof typeof slopeDraft]} oninput={event=>slopeDraft={...slopeDraft,[field]:event.currentTarget.value}} required/></label>{/each}</div>{#if slopeError}<p class="point-error" role="alert">{slopeError}</p>{/if}<button class="btn small" type="submit">Gefällepunkte übernehmen</button><button class="btn small" type="button" onclick={resetSlope}>Punkte zurücksetzen</button></form>{/if}
{#if element.kind==='connection'||element.kind==='clearance'||element.kind==='slope'||element.kind==='surface'||element.kind==='technical_note'}<label for={'technical-rule-'+element.id}>Geprüfte Ausführungs- / Flächenregel</label><ReferencePicker id={'technical-rule-'+element.id} reference="planning-rules" initial={choices(rules)} value={element.kind==='connection'?element.specificationVersionId??'':element.ruleVersionId??''} onchange={rule}/>{/if}
<details class="technical-details"><summary>Fachunterlagen verknüpfen · {element.sourceEvidenceVersionIds.length}</summary><p>Ein Quellenbezug dokumentiert die Grundlage. Er ersetzt weder ein bestätigtes Aufmaß noch eine Fachfreigabe.</p><ul>{#each element.sourceEvidenceVersionIds as id}<li><a href={'/document-versions/'+id} target="_blank" rel="noreferrer">{sourceName(id)}</a><button type="button" aria-label={'Quellenbezug '+sourceName(id)+' entfernen'} onclick={()=>onchange([{type:'set_element_sources',elementId:element.id,sourceEvidenceVersionIds:element.sourceEvidenceVersionIds.filter(value=>value!==id)}])}>Entfernen</button></li>{/each}</ul><label for={'technical-source-'+element.id}>Verfügbare Quellenversion</label><ReferencePicker id={'technical-source-'+element.id} reference="document-versions" initial={choices(documents)} value={sourceId} onchange={value=>sourceId=value}/><button type="button" class="btn small" disabled={!sourceId||element.sourceEvidenceVersionIds.includes(sourceId)} onclick={addSource}>Unterlage verknüpfen</button></details>
</section>
<style>
.technical-details{margin-top:16px;padding:11px 12px;border:1px solid var(--line-soft,var(--line));border-radius:11px;background:var(--input-surface)}.technical-details>summary{min-height:26px;color:var(--ink);font-size:12px;font-weight:500;cursor:pointer;line-height:1.6}
.point-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.point-fields input{display:block;box-sizing:border-box;width:100%;min-height:44px;margin-top:7px;padding:10px;font:inherit;font-size:14px;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:4px}.point-error{white-space:pre-wrap;border:1px solid var(--line);background:var(--danger-wash);padding:12px;color:var(--danger)}.slope-points .btn{margin-right:8px}@media(max-width:720px){.point-fields{grid-template-columns:repeat(2,minmax(0,1fr))}.point-fields input{min-height:48px;font-size:16px}}
.technical-references{margin-top:24px;border-top:1px solid var(--line);padding-top:18px;font-size:13px;line-height:1.65}.technical-references h3{font-size:14px;font-weight:600}.technical-references h4{font-size:13px;font-weight:600;margin:24px 0 8px}.technical-references p{font-size:12px;color:var(--muted);margin:10px 0 18px}.technical-references label{display:block;font-size:13px;margin:16px 0 7px}.technical-references select{display:block;box-sizing:border-box;width:100%;min-height:44px;margin-top:7px;padding:10px;font:inherit;font-size:14px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink)}.technical-references :global(select){width:100%;min-height:44px;font-size:14px}.technical-references .btn{font-size:12px;margin-top:12px;min-height:44px}.technical-references ul{list-style:none;margin:0;padding:0}.technical-references li{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:9px 0;font-size:12px}.technical-references a{color:var(--forest);overflow-wrap:anywhere}.technical-references li button{font-size:12px;min-height:40px;padding:5px 0;background:none;border:0;color:var(--forest);cursor:pointer}.technical-references .check{display:flex;gap:9px;align-items:start}.check input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--forest)}@media(max-width:720px){.technical-references select,.technical-references :global(select){min-height:48px;font-size:16px}.technical-references .btn,.technical-references li button{min-height:48px}}
</style>
